import { CredentialAccessData } from './credential-access-data';
import { CredentialUsageHandler } from './credential-usage-handler';
import { CredentialsResponseElementScope } from './credentials-response-element-scope';
import { CredentialsResponseElementScopesItem } from './credentials-response-element-scopes-item';
import { CredentialsResponseElementType } from './credentials-response-element-type';
import { ExternalVaultConfig } from './external-vault-config';
/**
 * Metadata of the credentials set.
 */
export interface CredentialsResponseElement {
    /**
     * Allow access without app context, for example, from ad hoc functions in Workflows (requires the APP_ENGINE scope).
     */
    allowContextlessRequests?: boolean;
    /**
     * The set of entities allowed to use the credential.
     */
    allowedEntities: CredentialAccessData[];
    /**
     * The list contains summary data related to the use of credentials.
     */
    credentialUsageSummary: CredentialUsageHandler[];
    /**
     * A short description of the credentials set.
     */
    description: string;
    externalVault?: ExternalVaultConfig;
    /**
     * The ID of the credentials set.
     */
    id?: string;
    /**
     * The name of the credentials set.
     */
    name: string;
    /**
     * The owner of the credential (user for which used API token was created).
     */
    owner: string;
    /**
     * Flag indicating that this credential is visible only to the owner.
     */
    ownerAccessOnly: boolean;
    scope?: CredentialsResponseElementScope;
    /**
     * The set of scopes of the credentials set.
     */
    scopes?: CredentialsResponseElementScopesItem[];
    type: CredentialsResponseElementType;
}
